// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import { createLink, pinLink, getLink, deleteLink } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const linkName = uniqueSuffix("testbot pin idempotent");
    const linkUrl = uniqueSuffix("https://example.com/testbot-pin-idempotent");

    const linksPostResponse = await createLink(
        client,
        URL_localhost,
        headers,
        linkName,
        linkUrl
    );

    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe(linkName);
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe(linkUrl);
    expect(getResponseValue(linksPostResponse, "response.id"), 'id').toBeGreaterThan(0);

    const linkId = getResponseValue(linksPostResponse, "response.id");

    const pinPatchResponse = await pinLink(client, URL_localhost, headers, linkId);

    expect(getResponseValue(pinPatchResponse, "response.id"), 'id').toBe(linkId);
    expect(getResponseValue(pinPatchResponse, "response.name"), 'name').toBe(linkName);
    expect(getResponseValue(pinPatchResponse, "response.url"), 'url').toBe(linkUrl);
    expect(getResponseValue(pinPatchResponse, "response.pinnedBy").length, 'pinnedBy length after first pin').toBe(1);
    expect(getResponseValue(pinPatchResponse, "response.pinnedBy.0.id"), 'pinnedBy.0.id').toBeGreaterThan(0);
    expect(getResponseValue(pinPatchResponse, "response.pinnedBy.1"), 'pinnedBy.1').toBeNull();
    expect(getResponseValue(pinPatchResponse, "response.updatedAt"), 'updatedAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const callerId = getResponseValue(pinPatchResponse, "response.pinnedBy.0.id");

    const pinPatch1Response = await pinLink(client, URL_localhost, headers, linkId);

    expect(pinPatch1Response.statusCode, 'status code').toBe(200);

    // docs/specs/pinning.md: "The call is idempotent. A second PATCH on a link the caller has
    // already pinned answers 200 and the link stays pinned; the caller's id appears once in pinnedBy."
    expect(getResponseValue(pinPatch1Response, "response.id"), 'id').toBe(linkId);
    expect(getResponseValue(pinPatch1Response, "response.name"), 'name').toBe(linkName);
    expect(getResponseValue(pinPatch1Response, "response.url"), 'url').toBe(linkUrl);
    expect(getResponseValue(pinPatch1Response, "response.pinnedBy").length, 'link stays pinned after second pin').toBe(1);
    expect(getResponseValue(pinPatch1Response, "response.pinnedBy.0.id"), 'caller id appears once in pinnedBy').toBe(callerId);
    expect(getResponseValue(pinPatch1Response, "response.pinnedBy.1"), 'pinnedBy.1').toBeNull();
    expect(getResponseValue(pinPatch1Response, "response.updatedAt"), 'updatedAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const linksLinksGetResponse = await getLink(client, URL_localhost, headers, linkId);

    expect(getResponseValue(linksLinksGetResponse, "response.id"), 'id').toBe(linkId);
    expect(getResponseValue(linksLinksGetResponse, "response.name"), 'name').toBe(linkName);
    expect(getResponseValue(linksLinksGetResponse, "response.url"), 'url').toBe(linkUrl);
    expect(getResponseValue(linksLinksGetResponse, "response.pinnedBy").length, 'link is still pinned on read-back').toBe(1);
    expect(getResponseValue(linksLinksGetResponse, "response.pinnedBy.0.id"), 'pinnedBy.0.id').toBe(callerId);
    expect(getResponseValue(linksLinksGetResponse, "response.pinnedBy.1"), 'pinnedBy.1').toBeNull();

    const linksLinksDeleteResponse = await deleteLink(client, URL_localhost, headers, linkId);

    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'id').toBe(linkId);
    expect(getResponseValue(linksLinksDeleteResponse, "response.name"), 'name').toBe(linkName);
});
